function isDisputeAllowed(bytes32 assertionId, address disputeCaller) public view virtual returns (bool) {
        // interpret low 20 bytes of assertionId as an address and allow only if it matches disputeCaller
        address encoded = address(uint160(uint256(assertionId)));
        return encoded == disputeCaller;
    }

